#include <list>

typedef unsigned long long big_int;

class stringx;

class string_buf
{
    friend class stringx;
    friend inline bool operator==(const stringx&, const stringx&);

    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;

public:
    inline bool is_equal(const string_buf &buf) const
    {
        if (buf.block_length != block_length)
            return false;
        for (int i = 0; i < block_length; i++)
            if (!(buf.data[i] == data[i]))
                return false;
        return true;
    }
};

class stringx
{
    friend inline bool operator==(const stringx&, const stringx&);

    char *chars;
    string_buf *my_buf;
};

inline bool operator==(const stringx &lhs, const stringx &rhs)
{
    return lhs.my_buf->is_equal(*rhs.my_buf);
}

class signaller;

class signal_callback
{
public:
    virtual ~signal_callback();
    virtual void spawn(signaller *source = 0) = 0;
    virtual bool is_code_callback() { return false; }
    virtual bool is_script_callback() { return false; }
};

class script_callback : public signal_callback
{
public:
    const stringx &get_func_name();
};

__asm__(".equ get_func_name__15script_callback, 0x0034BE60");

class signal
{
    int flavor;
    unsigned int flags;
    const char *signal_name;
    void *outputs;
    list<signal_callback*> callbacks;

public:
    void clear_script_callback(const stringx &name);
};

void signal::clear_script_callback(const stringx &name)
{
  list<signal_callback*>::iterator i = callbacks.begin();

  for ( ; i!=callbacks.end(); ++i )
  {
    signal_callback* sc = *i;
    if ( sc != NULL && sc->is_script_callback() && ((script_callback *)sc)->get_func_name() == name)
    {
      callbacks.erase(i);
      delete sc;

      return;
    }
  }
}
